271	    /**
272	     * The single derived key used for all duplicate detection, formatted
273	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
274	     * duplicates only when their whole identity keys are equal; because the telephone is part
275	     * of the key, two members of the same household with different telephones have different
276	     * keys and are both allowed.
277	     *
278	     * @return the derived identity key
279	     */
280	    @Transient
281	    public String getIdentityKey() {
282	        return (this.telephone == null ? "" : this.telephone) + "|"
283	            + (this.email == null ? "" : this.email) + "|"
284	            + (this.householdId == null ? "" : this.householdId);
285	    }
