287	    /**
288	     * A single Luhn check digit (0-9) computed over the digits contained in the
289	     * {@code customerCode}. Non-digit characters (such as the letter prefixes and the
290	     * separators) are ignored; a {@code null} customer code is treated as having no digits.
291	     *
292	     * @return the Luhn check digit for the customer code
293	     */
294	    @Transient
295	    public int getCheckDigit() {
296	        String source = this.customerCode == null ? "" : this.customerCode;
297	        int sum = 0;
298	        boolean dbl = true;
299	        for (int i = source.length() - 1; i >= 0; i--) {
300	            char c = source.charAt(i);
301	            if (c < '0' || c > '9') {
302	                continue;
303	            }
304	            int d = c - '0';
305	            if (dbl) {
306	                d *= 2;
307	                if (d > 9) {
308	                    d -= 9;
309	                }
310	            }
311	            sum += d;
312	            dbl = !dbl;
313	        }
314	        return (10 - (sum % 10)) % 10;
315	    }
